"""Check search/context/image workflows without network requests or patched HTML."""
import argparse,hashlib,json,uuid
from pathlib import Path

def run(folder,work,output,executable,headless=False,engine="chromium"):
 from playwright.sync_api import sync_playwright
 folder=Path(folder).resolve();work=Path(work).resolve()/('navigation-'+uuid.uuid4().hex[:10]);work.mkdir(parents=True);output=Path(output).resolve();output.mkdir(parents=True,exist_ok=True);checks=[];errors=[];network=[]
 def ok(v,label):
  if not v:raise AssertionError(label+'; runtime errors: '+json.dumps(errors,ensure_ascii=False))
  checks.append(label)
 with sync_playwright() as pw:
  c=getattr(pw,engine).launch_persistent_context(str(work/'profile'),executable_path=executable,headless=headless,viewport={'width':1440,'height':1000},offline=True);pg=c.pages[0];pg.on('pageerror',lambda e:errors.append(str(e)));pg.on('request',lambda q:network.append(q.url) if q.url.startswith(('http:','https:')) else None);pg.goto((folder/'reader.html').as_uri())
  pg.locator('[data-route=deep]').click();evidence=pg.locator('#mode-guide .story-refs a').nth(1);evidence.scroll_into_view_if_needed();before=pg.evaluate('({y:scrollY,hash:location.hash})');evidence.click()
  ok(pg.locator('#mode-full').is_visible() and pg.locator('#return-context').is_visible(),'证据直接跳回原文并提供返回入口');pg.locator('#return-context').click();ok(pg.locator('.guide-deep').is_visible() and abs(pg.evaluate('scrollY')-before['y'])<8 and pg.evaluate('location.hash')==before['hash'],'返回原讲解、位置与原URL片段')
  pg.locator('[data-route=quick]').click();pg.locator('#search').fill('the');ok(pg.locator('#mode-full').is_visible() and pg.locator('.search-hit').count()>0,'搜索原文并显示字面匹配');ok(pg.locator('.search-controls').is_visible(),'搜索有前后段落导航')
  current=pg.locator('.search-current').get_attribute('id');pg.locator('[data-search-next]').click();ok(pg.locator('.search-current').get_attribute('id')!=current,'下一处改变当前匹配段落');pg.locator('[data-search-prev]').click();ok(pg.locator('.search-current').get_attribute('id')==current,'上一处回到原匹配')
  pg.locator('#search').press('Enter');ok(pg.locator('.search-current').get_attribute('id')!=current,'Enter走到下一个匹配');pg.locator('#search').press('Shift+Enter');ok(pg.locator('.search-current').get_attribute('id')==current,'Shift+Enter走到上一个匹配');pg.locator('#search').press('Escape');ok(pg.locator('#story-overview').is_visible() and not pg.locator('.guide-deep').is_visible() and pg.locator('.search-hit').count()==0,'退出搜索回到原三分钟路线并移除临时高亮')
  pg.locator('#resume').click();ok(pg.locator('#story-overview').is_visible() and not pg.locator('.guide-deep').is_visible(),'继续三分钟位置不会切成十分钟')
  for term in ['(', '[', '25.0', 'Ca²+', '<script>']:
   pg.locator('#search').fill(term);ok(not errors,'搜索特殊字符作为字面量：'+term)
  pg.locator('#search').fill('NONEXISTENT_LITERAL_QUERY_987654321');ok('没有匹配' in pg.locator('#search-count').inner_text() and pg.locator('[data-search-next]').is_disabled(),'无结果有反馈且导航禁用');pg.locator('[data-search-clear]').click()
  pg.locator('[data-route=full]').click();pg.evaluate('''()=>{const el=[...document.querySelectorAll('.pcard .orig')].find(e=>e.textContent.length>100);el.scrollIntoView({block:'center'});const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode())if(n.length>40){const r=document.createRange();r.setStart(n,0);r.setEnd(n,20);getSelection().removeAllRanges();getSelection().addRange(r);break;}}''');pg.wait_for_timeout(180);pg.locator('#annbar [data-h]').click();quote=pg.evaluate('__ann.items[0].text');pg.locator('#search').fill(quote);pg.locator('[data-search-clear]').click();ok(pg.locator('mark[data-ann]').count()>0 and pg.evaluate('__ann.items[0].text')==quote,'搜索高亮与个人高亮互不破坏')
  figures=pg.locator('.figure-trigger');figure_checks='not present in this source'
  if figures.count():
   trigger=figures.first;trigger.click();ok(pg.locator('#figure-viewer').is_visible(),'原图可原地放大查看');ok(pg.locator('#figure-viewer img').evaluate('(img)=>img.complete&&img.naturalWidth>0'),'放大图实际加载');ok(pg.locator('#figure-viewer').evaluate('(d)=>{const a=d.querySelector("img").getBoundingClientRect(),b=d.querySelector(".figure-stage").getBoundingClientRect();return a.top>=b.top-1&&a.bottom<=b.bottom+1&&d.scrollHeight<=d.clientHeight+2}'),'适应窗口时整张原图可见');pg.locator('#figure-viewer [data-actual]').click();ok(pg.locator('.figure-stage').evaluate('(x)=>x.classList.contains("actual-size")'),'原始尺寸在图内滚动查看');pg.locator('#figure-viewer [data-fit]').click();ok(not pg.locator('.figure-stage').evaluate('(x)=>x.classList.contains("actual-size")'),'可恢复适应窗口');pg.locator('#figure-viewer').screenshot(path=str(output/(folder.name+'-figure.png')));pg.keyboard.press('Escape');ok(pg.evaluate('document.activeElement.classList.contains("figure-trigger")'),'关闭原图回到原触发控件')
   pg.emulate_media(media='print');ok(trigger.evaluate('(b)=>getComputedStyle(b).display!=="none"'),'打印仍保留原图而非被按钮规则隐藏');pg.emulate_media(media='screen');pg.set_viewport_size({'width':390,'height':844});trigger.click();ok(pg.evaluate('document.documentElement.scrollWidth<=innerWidth'),'390px图表查看无整页横溢');pg.keyboard.press('Escape');figure_checks='passed'
  pg.set_viewport_size({'width':390,'height':844});pg.locator('#search').fill('the');ok(pg.evaluate('document.documentElement.scrollWidth<=innerWidth'),'390px搜索导航无横溢');pg.screenshot(path=str(output/(folder.name+'-search-mobile.png')));pg.locator('[data-search-clear]').click();ok(not errors,'所有流程无浏览器运行错误');ok(not network,'离线无外部请求');c.close()
 result={'folder':folder.name,'html_sha256':hashlib.sha256((folder/'reader.html').read_bytes()).hexdigest(),'browser':engine+(' headed' if not headless else ' headless'),'passed':len(checks),'checks':checks,'figure_checks':figure_checks,'errors':errors,'external_requests':network};(output/(folder.name+'-navigation-results.json')).write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8');print(folder.name,len(checks),'navigation checks passed',flush=True);return result
if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('folder',type=Path);p.add_argument('--work-dir',required=True,type=Path);p.add_argument('--output',required=True,type=Path);p.add_argument('--browser-executable');p.add_argument('--browser',choices=['chromium','firefox','webkit'],default='chromium');p.add_argument('--headless',action='store_true');a=p.parse_args();run(a.folder,a.work_dir,a.output,a.browser_executable,a.headless,a.browser)
